17	
18	import java.util.Locale;
19	import java.util.function.Predicate;
20	
21	import org.springframework.samples.petclinic.model.Sha256;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Builds an owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where
26	 * REGION is the owner's canonical region (see
27	 * {@link org.springframework.samples.petclinic.model.RegionResolver}) and HASH8 is the
28	 * first eight upper-case hexadecimal characters of the SHA-256 hash over the owner's
29	 * normalized telephone followed by its last name. The identity is derived purely from
30	 * the owner's own fields, carrying no sequence number.
31	 */
32	@Component
33	public class CustomerCodeGenerator {
34	
35	    private static final int HASH_LENGTH = 8;
36	
37	    /**
38	     * Build the customer code for a new owner.
39	     *
40	     * @param region             the owner's canonical region
41	     * @param normalizedTelephone the owner's normalized (E.164) telephone
42	     * @param lastName           the owner's last name
43	     * @return the formatted customer code, e.g. {@code "NSW-1A2B3C4D"}
44	     */
45	    public String generate(String region, String normalizedTelephone, String lastName) {
46	        return region + "-" + hash8(normalizedTelephone, lastName);
47	    }
48	
49	    /**
50	     * Build a customer code that does not collide with any already in use. The code is
51	     * derived exactly as {@link #generate(String, String, String)}; when that value is
52	     * already taken, {@code '-<n>'} is appended with the smallest {@code n} of two or more
53	     * that yields an unused code.
54	     *
55	     * @param region              the owner's canonical region
56	     * @param normalizedTelephone the owner's normalized (E.164) telephone
57	     * @param lastName            the owner's last name
58	     * @param isTaken             tests whether a candidate code is already in use
59	     * @return a customer code not reported as taken by {@code isTaken}
60	     */
61	    public String generateUnique(String region, String normalizedTelephone, String lastName,
62	            Predicate<String> isTaken) {
63	        String base = generate(region, normalizedTelephone, lastName);
64	        String candidate = base;
65	        for (int n = 2; isTaken.test(candidate); n++) {
66	            candidate = base + "-" + n;
67	        }
68	        return candidate;
69	    }
70	
71	    private String hash8(String normalizedTelephone, String lastName) {
72	        String identity = safe(normalizedTelephone) + safe(lastName);
73	        return Sha256.hex(identity).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
74	    }
75	
76	    private String safe(String value) {
77	        return value == null ? "" : value;
78	    }
79	}
